CREATE TABLE claim_fiscal_number (
    sheet_id VARCHAR(100) NOT NULL,
    fiscal_year VARCHAR(10) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, fiscal_year)
);
